WITH RECURSIVE comment_tree AS ( SELECT id FROM blog_comment WHERE id = #{commentId}
UNION ALL
SELECT c.id FROM blog_comment c INNER JOIN comment_tree ct ON c.parent_id = ct.id ) SELECT id FROM comment_tree

WITH RECURSIVE comment_tree AS ( SELECT id FROM blog_comment WHERE id = #{commentId}
UNION ALL
SELECT c.id FROM blog_comment c INNER JOIN comment_tree ct ON c.parent_id = ct.id ) SELECT COUNT(*) FROM blog_comment c INNER JOIN comment_tree ct ON c.id = ct.id WHERE c.status = 'APPROVED'

SELECT root_id, COUNT(*) FILTER (WHERE status = 'APPROVED') AS reply_count, COUNT(*) AS visible_reply_count FROM blog_comment WHERE root_id IN
#{rootId}
AND ( status = 'APPROVED'
OR ( user_id = #{currentUserId} AND status IN ('PENDING', 'REJECTED') )
) GROUP BY root_id
